    {R : Sheaf J RingCat.{max u v w}} {S : Sheaf K RingCat.{max u v w}}
    (a : R ⟶ (U.sheafPushforwardContinuous RingCat J K).obj S) :
    (SheafOfModules.pushforward.{max u v w} a).IsRightAdjoint
